package org.sigf.repositories;
import java.sql.*;import java.math.BigDecimal;import org.sigf.config.Database;
public final class ReceiptRepository {
 private final Database db;public ReceiptRepository(Database db){this.db=db;}
 public String receipt(long sale)throws SQLException {StringBuilder out=new StringBuilder();try(Connection c=db.connection()){try(PreparedStatement s=c.prepareStatement("select s.id,s.created_at,s.subtotal,s.tax,s.total,s.status,coalesce(h.customer_name,c.name,'Consumidor final'),coalesce(h.currency,(select value from setting where key='currency'),'NIO'),coalesce(h.pharmacy_name,(select value from setting where key='pharmacy_name'),'Farmacia'),coalesce(h.ruc,(select ruc from pharmacy_profile where id=1),''),coalesce(h.address,(select address from pharmacy_profile where id=1),''),coalesce(h.phone,(select phone from pharmacy_profile where id=1),''),coalesce(h.email,(select email from pharmacy_profile where id=1),''),h.sale_id is null,coalesce(d.series,''),d.number,coalesce(h.customer_ruc,'') from sale s left join internal_document d on d.sale_id=s.id left join customer c on c.id=s.customer_id left join sale_receipt_snapshot h on h.sale_id=s.id where s.id=?")){s.setLong(1,sale);try(ResultSet r=s.executeQuery()){if(!r.next())throw new IllegalArgumentException("Venta inexistente");out.append("COMPROBANTE INTERNO - SIN VALOR FISCAL\n");if(r.getBoolean(14))out.append("DOCUMENTO ANTERIOR: DATOS HISTÓRICOS NO DISPONIBLES\n");out.append(r.getString(9)).append("\n");if(!r.getString(10).isBlank())out.append("RUC: ").append(r.getString(10)).append("\n");if(!r.getString(11).isBlank())out.append(r.getString(11)).append("\n");if(!r.getString(12).isBlank())out.append("Tel: ").append(r.getString(12)).append("\n");if(!r.getString(13).isBlank())out.append(r.getString(13)).append("\n");if(!r.getString(15).isBlank())out.append("Serie interna: ").append(r.getString(15)).append("-").append(r.getLong(16)).append("\n");out.append("Venta #").append(r.getLong(1)).append(" · ").append(r.getString(2)).append("\nCliente: ").append(r.getString(7));if(!r.getString(17).isBlank())out.append(" · RUC ").append(r.getString(17));out.append("\nEstado: ").append(r.getString(6)).append("\n\n");out.append("Subtotal: ").append(r.getBigDecimal(3)).append(" ").append(r.getString(8)).append("\nImpuesto: ").append(r.getBigDecimal(4)).append("\nTotal: ").append(r.getBigDecimal(5)).append("\n\nDetalle:\n");}}try(PreparedStatement s=c.prepareStatement("select coalesce(l.product_name_snapshot,p.name),sum(l.quantity),l.unit_price,l.tax_rate from sale_line l join product p on p.id=l.product_id where l.sale_id=? group by l.product_id,coalesce(l.product_name_snapshot,p.name),l.unit_price,l.tax_rate order by 1")){s.setLong(1,sale);try(ResultSet r=s.executeQuery()){while(r.next())out.append(r.getString(1)).append(" · ").append(r.getInt(2)).append(" x ").append(r.getBigDecimal(3)).append(" · IVA ").append(r.getBigDecimal(4)==null?"histórico sin clasificación":r.getBigDecimal(4).multiply(new BigDecimal("100")).stripTrailingZeros().toPlainString()+"%").append("\n");}}try(PreparedStatement s=c.prepareStatement("select method,amount,received_amount,change_amount from payment where sale_id=?")){s.setLong(1,sale);try(ResultSet r=s.executeQuery()){while(r.next()){out.append("Pago ").append(r.getString(1)).append(": ").append(r.getBigDecimal(2)).append("\n");if(r.getBigDecimal(3)!=null)out.append("Recibido: ").append(r.getBigDecimal(3)).append(" · Cambio: ").append(r.getBigDecimal(4)).append("\n");}}}}return out.toString();}
}
